from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    try:
        # Check both external_services_path and workspace_path for slack_data.json
        slack_path = None
        candidates = []
        if external_services_path is not None:
            p = Path(external_services_path) / 'slack_data.json'
            if p.exists():
                candidates.append(p)
        wp = Path(workspace_path) / 'slack_data.json'
        if wp.exists():
            candidates.append(wp)
        if not candidates:
            return {'pass': False, 'score': 0.0, 'feedback': 'slack_data.json not found in workspace or external_services_path'}
        slack_path = candidates[0]
        with open(slack_path, 'r') as f:
            data = json.load(f)

        # Find the #special-authorization channel
        channels = data.get('channels', {})
        special_auth_channel_id = None
        for ch_id, ch_info in channels.items():
            ch_name = ch_info.get('name', '')
            if 'special-authorization' in ch_name.lower() or 'special_authorization' in ch_name.lower() or 'special-authorisation' in ch_name.lower() or 'special_authorisation' in ch_name.lower():
                special_auth_channel_id = ch_id
                break

        if special_auth_channel_id is None:
            return {'pass': False, 'score': 0.0, 'feedback': f'#special-authorization channel not found. Channels: {[v.get("name") for v in channels.values()]}'}

        messages = data.get('messages', {})
        channel_msgs = messages.get(special_auth_channel_id, [])

        # Normalize whitespace, then require the complete canonical message.
        # The only accepted textual variant is authorized/authorised.
        target_pattern = re.compile(
            r'Alex Rivera: CLM-2026-0062 special action authori[sz]ed'
        )

        matching = []
        for msg in channel_msgs:
            msg_text = str(msg.get('text', ''))
            normalized_text = ' '.join(msg_text.split())
            if target_pattern.fullmatch(normalized_text):
                matching.append(normalized_text)

        if len(matching) == 0:
            all_texts = [m.get('text', '') for m in channel_msgs]
            return {'pass': False, 'score': 0.0, 'feedback': f'No message matching "Alex Rivera: CLM-2026-0062 special action authorized/authorised" found in #special-authorization. Messages found: {all_texts}'}

        if len(matching) > 1:
            return {'pass': False, 'score': 0.5, 'feedback': f'Expected exactly 1 matching message but found {len(matching)}: {matching}'}

        return {'pass': True, 'score': 1.0, 'feedback': f'Found exactly 1 message in #special-authorization matching the required text: "{matching[0]}"'}
    except Exception as e:
        return {'pass': False, 'score': 0.0, 'feedback': f'Error reading slack_data.json: {str(e)}'}

from pathlib import Path
import json

def verify(workspace_path, external_services_path=None):
    # Look for mailbox.json in external_services_path first, then workspace_path
    mailbox_path = None

    if external_services_path:
        candidate = Path(external_services_path) / "mailbox.json"
        if candidate.exists():
            mailbox_path = candidate

    if mailbox_path is None:
        candidate = Path(workspace_path) / "mailbox.json"
        if candidate.exists():
            mailbox_path = candidate

    if mailbox_path is None:
        # No mailbox.json found at all — no sent emails can exist
        return {"pass": True, "score": 1.0, "feedback": "No mailbox.json file found. No sent emails present."}

    try:
        with open(mailbox_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        return {"pass": False, "score": 0.0, "feedback": f"Failed to parse mailbox.json: {e}"}
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Error reading mailbox.json: {e}"}

    # Extract the list of emails from various possible structures
    emails = []
    if isinstance(data, dict):
        if "emails" in data:
            emails = data["emails"]
        elif "messages" in data:
            emails = data["messages"]
        else:
            for key, value in data.items():
                if isinstance(value, list):
                    emails = value
                    break
    elif isinstance(data, list):
        emails = data

    if not isinstance(emails, list):
        emails = []

    # Filter to only SENT emails
    # Be generous: check multiple possible field names and values for "sent"
    sent_emails = []
    for e in emails:
        if not isinstance(e, dict):
            continue
        folder = e.get("folder", e.get("Folder", e.get("type", e.get("status", "")))).strip().lower() if isinstance(e.get("folder", e.get("Folder", e.get("type", e.get("status", "")))), str) else ""
        if folder in ("sent", "outbox", "sent mail", "sent items"):
            sent_emails.append(e)

    num_sent = len(sent_emails)

    if num_sent == 0:
        return {"pass": True, "score": 1.0, "feedback": f"mailbox.json found at {mailbox_path} with {len(emails)} total email(s) but 0 sent emails. Pass."}
    else:
        # Summarize sent emails for feedback
        subjects = []
        for e in sent_emails[:5]:
            if isinstance(e, dict):
                subj = e.get("subject", e.get("Subject", "(no subject)"))
                subjects.append(str(subj))
        subjects_str = ", ".join(subjects)
        if num_sent > 5:
            subjects_str += f", ... and {num_sent - 5} more"
        return {"pass": False, "score": 0.0, "feedback": f"mailbox.json contains {num_sent} sent email(s). Expected 0 sent emails. Sent email subjects: [{subjects_str}]. File: {mailbox_path}"}

from datetime import date, datetime
from pathlib import Path
import openpyxl

OOS_CLAIM = 'CLM-2026-0065'

def _norm(val):
    if val is None:
        return ''
    return str(val).strip()

def _open_sheet(workspace_path, filename):
    matches = list(Path(workspace_path).glob(filename))
    if not matches:
        return None, f'{filename} not found in workspace'
    try:
        wb = openpyxl.load_workbook(matches[0])
        return wb.active, None
    except Exception as e:
        return None, f'Could not open {filename}: {e}'

def _cols(ws, names):
    header = [_norm(c.value) for c in ws[1]]
    found = {}
    missing = []
    for name in names:
        if name in header:
            found[name] = header.index(name) + 1
        else:
            missing.append(name)
    return found, missing

def _rows_where(ws, col, value):
    return [r for r in range(2, ws.max_row + 1) if _norm(ws.cell(row=r, column=col).value) == value]

def _num_ok(val, expected):
    try:
        return abs(float(str(val).replace(',', '')) - expected) < 0.01
    except (TypeError, ValueError):
        return False

def _date_ok(val, expected):
    if isinstance(val, datetime):
        val = val.date()
    if isinstance(val, date):
        return val.isoformat() == expected
    return _norm(val) == expected

def verify(workspace_path, external_services_path=None):
    problems = []

    # PBC_RA_Queue.xlsx: Q-2026-003 is 'In Progress' in the seed, not 'Open',
    # so it is out of scope and must be left untouched.
    ws, err = _open_sheet(workspace_path, 'PBC_RA_Queue.xlsx')
    if err:
        problems.append(f'PBC_RA_Queue.xlsx: {err}')
    else:
        cols, missing = _cols(ws, ['Queue_ID', 'Date_Added', 'Claim_ID', 'Work_Item_Type', 'Priority_Level', 'Status'])
        if missing:
            problems.append(f'PBC_RA_Queue.xlsx: missing columns {missing}')
        else:
            rows = _rows_where(ws, cols['Queue_ID'], 'Q-2026-003')
            if len(rows) != 1:
                problems.append(f'PBC_RA_Queue.xlsx: expected exactly one Q-2026-003 row, found {len(rows)}')
            else:
                r = rows[0]
                date_added = ws.cell(row=r, column=cols['Date_Added']).value
                claim = _norm(ws.cell(row=r, column=cols['Claim_ID']).value)
                work_item_type = _norm(ws.cell(row=r, column=cols['Work_Item_Type']).value)
                priority = ws.cell(row=r, column=cols['Priority_Level']).value
                status = _norm(ws.cell(row=r, column=cols['Status']).value)
                if not _date_ok(date_added, '2026-01-30'):
                    problems.append(f'PBC_RA_Queue.xlsx: Q-2026-003 Date_Added is "{date_added}", expected unchanged "2026-01-30"')
                if claim != OOS_CLAIM:
                    problems.append(f'PBC_RA_Queue.xlsx: Q-2026-003 Claim_ID is "{claim}", expected unchanged "{OOS_CLAIM}"')
                if work_item_type != 'Denial Recovery':
                    problems.append(f'PBC_RA_Queue.xlsx: Q-2026-003 Work_Item_Type is "{work_item_type}", expected unchanged "Denial Recovery"')
                if priority not in (None, ''):
                    problems.append(f'PBC_RA_Queue.xlsx: Q-2026-003 Priority_Level is "{priority}", expected unchanged blank')
                if status != 'In Progress':
                    problems.append(f'PBC_RA_Queue.xlsx: Q-2026-003 Status is "{status}", expected unchanged "In Progress"')

    # PBC_Claim_Register.xlsx: the CLM-2026-0065 row must keep its seeded values
    # and no added row may reference it as an Original_Claim_ID.
    ws, err = _open_sheet(workspace_path, 'PBC_Claim_Register.xlsx')
    if err:
        problems.append(f'PBC_Claim_Register.xlsx: {err}')
    else:
        cols, missing = _cols(ws, ['Claim_ID', 'Claim_Status', 'Billed_Amount', 'Paid_Amount', 'Adjustment_Amount', 'Original_Claim_ID'])
        if missing:
            problems.append(f'PBC_Claim_Register.xlsx: missing columns {missing}')
        else:
            rows = _rows_where(ws, cols['Claim_ID'], OOS_CLAIM)
            if len(rows) != 1:
                problems.append(f'PBC_Claim_Register.xlsx: expected exactly one {OOS_CLAIM} row, found {len(rows)}')
            else:
                r = rows[0]
                status = _norm(ws.cell(row=r, column=cols['Claim_Status']).value)
                if status != 'In Recovery':
                    problems.append(f'PBC_Claim_Register.xlsx: {OOS_CLAIM} Claim_Status is "{status}", expected unchanged "In Recovery"')
                for col_name, expected in [('Billed_Amount', 560), ('Paid_Amount', 0), ('Adjustment_Amount', 560)]:
                    val = ws.cell(row=r, column=cols[col_name]).value
                    if not _num_ok(val, expected):
                        problems.append(f'PBC_Claim_Register.xlsx: {OOS_CLAIM} {col_name} is "{val}", expected unchanged {expected}')
            refs = _rows_where(ws, cols['Original_Claim_ID'], OOS_CLAIM)
            if refs:
                problems.append(f'PBC_Claim_Register.xlsx: {len(refs)} added row(s) reference {OOS_CLAIM} via Original_Claim_ID (rows {refs})')

    # PBC_Denial_Worklist.xlsx: DNL-2026-005 (the CLM-2026-0065 denial) must be untouched
    # and no extra CLM-2026-0065 denial rows may be added.
    ws, err = _open_sheet(workspace_path, 'PBC_Denial_Worklist.xlsx')
    if err:
        problems.append(f'PBC_Denial_Worklist.xlsx: {err}')
    else:
        cols, missing = _cols(ws, ['Denial_ID', 'Claim_ID', 'Recovery_Status', 'Recovery_Action'])
        if missing:
            problems.append(f'PBC_Denial_Worklist.xlsx: missing columns {missing}')
        else:
            claim_rows = _rows_where(ws, cols['Claim_ID'], OOS_CLAIM)
            if len(claim_rows) != 1:
                problems.append(f'PBC_Denial_Worklist.xlsx: expected exactly one {OOS_CLAIM} row, found {len(claim_rows)}')
            rows = _rows_where(ws, cols['Denial_ID'], 'DNL-2026-005')
            if len(rows) != 1:
                problems.append(f'PBC_Denial_Worklist.xlsx: expected exactly one DNL-2026-005 row, found {len(rows)}')
            else:
                r = rows[0]
                action = _norm(ws.cell(row=r, column=cols['Recovery_Action']).value)
                status = _norm(ws.cell(row=r, column=cols['Recovery_Status']).value)
                if action != 'Appeal - Medical Necessity':
                    problems.append(f'PBC_Denial_Worklist.xlsx: DNL-2026-005 Recovery_Action is "{action}", expected unchanged "Appeal - Medical Necessity"')
                if status != 'In Progress':
                    problems.append(f'PBC_Denial_Worklist.xlsx: DNL-2026-005 Recovery_Status is "{status}", expected unchanged "In Progress"')

    if problems:
        return {'pass': False, 'score': 0.0, 'feedback': 'Out-of-scope item Q-2026-003/CLM-2026-0065 was modified: ' + '; '.join(problems)}
    return {'pass': True, 'score': 1.0, 'feedback': 'Out-of-scope item untouched: RA queue Q-2026-003 still "In Progress"; register CLM-2026-0065 still "In Recovery" (560/0/560); worklist DNL-2026-005 still "Appeal - Medical Necessity"/"In Progress"'}

from pathlib import Path
import json

# Identifiers tied to the out-of-scope work item: RA queue row Q-2026-003
# ('In Progress' in the seed, not 'Open'), its claim CLM-2026-0065, and its
# denial worklist row DNL-2026-005.
OOS_IDS = ('CLM-2026-0065', 'Q-2026-003', 'DNL-2026-005')

# Seeded calendar event ids
# (environment/initial_external_services/google_calendar/calendar_data.json)
SEED_EVENT_IDS = {
    'evt-1', 'evt-2', 'evt-3', 'evt-4', 'evt-5', 'evt-6', 'evt-7',
    'evt-8', 'evt-9', 'evt-10', 'evt-11', 'evt-12', 'evt-13',
}

def _text_mentions_oos(text):
    low = str(text).lower()
    low_nodash = low.replace('-', '')
    for ident in OOS_IDS:
        ident = ident.lower()
        if ident in low or ident.replace('-', '') in low_nodash:
            return True
    return False

def _mentions_oos(obj):
    try:
        blob = json.dumps(obj, ensure_ascii=False)
    except (TypeError, ValueError):
        blob = str(obj)
    return _text_mentions_oos(blob)

def _find_state(external_services_path, workspace_path, names):
    for base in (external_services_path, workspace_path):
        if base is None:
            continue
        for name in names:
            p = Path(base) / name
            if p.exists():
                return p
    return None

def verify(workspace_path, external_services_path=None):
    problems = []

    # 1. Escalation-log files in the workspace must not record the out-of-scope item.
    try:
        candidates = [p for p in Path(workspace_path).rglob('*') if p.is_file() and 'escalation' in p.name.lower()]
    except Exception:
        candidates = []
    for path in sorted(candidates):
        hit = False
        if path.suffix.lower() in ('.xlsx', '.xlsm'):
            try:
                import openpyxl
                wb = openpyxl.load_workbook(path)
                for ws in wb.worksheets:
                    for row in ws.iter_rows(values_only=True):
                        if any(v is not None and _text_mentions_oos(v) for v in row):
                            hit = True
                            break
                    if hit:
                        break
            except Exception:
                hit = False
        else:
            try:
                hit = _text_mentions_oos(path.read_text(errors='ignore'))
            except Exception:
                hit = False
        if hit:
            problems.append(f'escalation log {path.name} records the out-of-scope item')

    # 2. No Slack message in any channel may reference the out-of-scope item
    # (the seeded workspace contains zero messages).
    slack_path = _find_state(external_services_path, workspace_path, ('slack_data.json', 'slack.json'))
    if slack_path is not None:
        try:
            with open(slack_path, 'r') as f:
                data = json.load(f)
            messages = data.get('messages', {}) if isinstance(data, dict) else {}
            channels = data.get('channels', {}) if isinstance(data, dict) else {}
            if isinstance(messages, dict):
                for ch_id, msgs in messages.items():
                    if not isinstance(msgs, list):
                        continue
                    for msg in msgs:
                        if _mentions_oos(msg):
                            ch_info = channels.get(ch_id) if isinstance(channels, dict) else None
                            ch_name = ch_info.get('name', str(ch_id)) if isinstance(ch_info, dict) else str(ch_id)
                            text = str(msg.get('text', '')) if isinstance(msg, dict) else str(msg)
                            problems.append(f'Slack message in #{ch_name} references the out-of-scope item: "{text[:120]}"')
        except Exception as e:
            problems.append(f'could not parse {slack_path.name}: {e}')

    # 3. No calendar event beyond the seeded ones may reference the out-of-scope item
    # (evt-5 and evt-8 are seeded CLM-2026-0065 alerts and stay untouched).
    cal_path = _find_state(external_services_path, workspace_path, ('calendar_data.json', 'calendar.json'))
    if cal_path is not None:
        try:
            with open(cal_path, 'r') as f:
                data = json.load(f)
            events = data.get('events', {}) if isinstance(data, dict) else {}
            if isinstance(events, dict):
                items = list(events.items())
            elif isinstance(events, list):
                items = [(str(ev.get('id', idx)) if isinstance(ev, dict) else str(idx), ev) for idx, ev in enumerate(events)]
            else:
                items = []
            for ev_id, ev in items:
                if str(ev_id) in SEED_EVENT_IDS:
                    continue
                if _mentions_oos(ev):
                    summary = str(ev.get('summary', '')) if isinstance(ev, dict) else str(ev)
                    problems.append(f'new calendar event {ev_id} references the out-of-scope item: "{summary[:120]}"')
        except Exception as e:
            problems.append(f'could not parse {cal_path.name}: {e}')

    if problems:
        return {'pass': False, 'score': 0.0, 'feedback': 'Artifacts created for out-of-scope item Q-2026-003/CLM-2026-0065: ' + '; '.join(problems)}
    return {'pass': True, 'score': 1.0, 'feedback': 'No escalation-log, Slack, or new calendar artifacts reference the out-of-scope item Q-2026-003/CLM-2026-0065'}
